PT=TB@TB.conj().T
for n in ("Lab","Lba","Rab","Rba"):
    Mx=M[n]; print(n,"leak out of T (||(1-P_T) M P_T||):",round(float(np.linalg.norm((np.eye(6)-PT)@Mx@PT)),6),"  leak T-bar->T:",round(float(np.linalg.norm(PT@Mx@(np.eye(6)-PT))),6))
# group generated by all four on V: order, commutant
def order(gens,maxn=5000):
    G=[np.eye(6,dtype=complex)];q=[G[0]];keys={tuple(np.round(G[0],5).flatten())}
    while q:
        c=q.pop()
        for g in gens:
            n=c@g;k=tuple(np.round(n,5).flatten()+0)
            if k not in keys: keys.add(k);G.append(n);q.append(n)
            if len(G)>maxn: return G
    return G
G=order([M["Lab"],M["Lba"],M["Rab"],M["Rba"]])
print("order of group generated by all four shear lifts on V:",len(G))
ip=sum(abs(np.trace(g))**2 for g in G)/len(G); print("<chi,chi>",ip)
def comm(gens):
    n=6;A=np.vstack([np.kron(g.T,np.eye(n))-np.kron(np.eye(n),g) for g in gens]);s=np.linalg.svd(A,compute_uv=False);return int(sum(s<1e-8))
print("commutant dim of the 4-shear group on V:",comm([M[k] for k in ("Lab","Lba","Rab","Rba")]))
